Given the head of a linked list, reverse the list and return the new head.Examples: Input: Output: 5 -> 4 -> 3 -> 2 -> 1Try It YourselfTable of Content[Approach] Using Iterative Method - O(n) Time and O(1) Space[Alternate Approach 1] Using Recursion Method- O(n) Time and O(n) Space[Alternate Approach 2] Using Stack - O(n) Time and O(n) Space[Approach] Using Iterative Method - O(n) Time and O(1) SpaceThe idea is to reverse the linked list by changing the direction of links using three pointers: prev, curr, and next. At each step, point the current node to its previous node and then move all three pointers forward until the list is fully reversed.
            C++

    #include <iostream>
using namespace std;

class Node {
  public:
    int data;
    Node *next;

    Node(int new_data) {
        data = new_data;
        next = nullptr;
    }
};

Node *reverseList(Node *head) {

    Node *curr = head, *prev = nullptr, *next;

    // Traverse all the nodes of Linked List
    while (curr != nullptr) {

        // Store next
        next = curr->next;

        // Reverse current node's next pointer
        curr->next = prev;

        // Move pointers one position ahead
        prev = curr;
        curr = next;
    }

    return prev;
}

void printList(Node *node) {
    while (node != nullptr) {
        cout << node->data;
        if (node->next)
            cout << " -> ";
        node = node->next;
    }
}

int main() {

    Node *head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(4);
    head->next->next->next->next = new Node(5);

    head = reverseList(head);

    printList(head);

    return 0;
}


